package com.nexus.hub.modules.task.entity;

import com.nexus.hub.modules.tenant.entity.Tenant;
import com.nexus.hub.modules.user.entity.User;
import jakarta.persistence.*;
import lombok.*;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;
import org.springframework.data.domain.Persistable;

import java.time.Instant;
import java.util.UUID;

/**
 * Document metadata. The id is ASSIGNED by DocumentService (it is also used for the on-disk
 * filename and the Qdrant vectors), so it must not be generated by Hibernate. Implementing
 * {@link Persistable} makes {@code repository.save()} call {@code persist()} for new documents
 * instead of {@code merge()}, which would otherwise insert a copy under a different id.
 */
@Entity
@Table(name = "documents", schema = "core")
@Getter
@Setter
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class Document implements Persistable<UUID> {

    @Id
    private UUID id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "tenant_id", nullable = false)
    private Tenant tenant;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "user_id", nullable = false)
    private User user;

    @Column(nullable = false)
    private String filename;

    @Column(name = "file_path", nullable = false, length = 500)
    private String filePath;

    @Column(name = "file_size", nullable = false)
    private Long fileSize;

    @Column(name = "mime_type", nullable = false, length = 100)
    private String mimeType;

    @Column(name = "vector_collection", nullable = false, length = 100)
    @Builder.Default
    private String vectorCollection = "enterprise_docs";

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 30)
    @Builder.Default
    private DocumentStatus status = DocumentStatus.UPLOADED;

    @Column(name = "chunks_count", nullable = false)
    @Builder.Default
    private Integer chunksCount = 0;

    /** Reason for FAILED status (ingestion error from ai-service or dispatch failure); null otherwise. */
    @Column(name = "error_details", columnDefinition = "TEXT")
    private String errorDetails;

    @CreationTimestamp
    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @UpdateTimestamp
    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    /** True until the entity has been persisted or loaded from the database. */
    @Transient
    @Builder.Default
    @Getter(AccessLevel.NONE)
    @Setter(AccessLevel.NONE)
    private boolean isNew = true;

    @Override
    public boolean isNew() {
        return isNew;
    }

    @PostLoad
    @PostPersist
    void markNotNew() {
        this.isNew = false;
    }
}
